        for c in x:
            num = c * n1 + n0
            den = c * d1 + d0
            yield num, den
            n0, n1 = n1, num
            d0, d1 = d1, den

    def rational_to_contfrac(p, q):
        while q:
            n = p // q
            yield n
            p, q = q, p - q * n

    quotients = rational_to_contfrac(e, n)
    for k, d in convergents(quotients):
